function cleanStr(str) {
  if (!str) return '';
  return str
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

/**
 * Autenticación robusta de estudiantes:
 * - Si te inscribiste a partir del 11 de noviembre, tu contraseña es el DNI.
 * - Soporta DNI como contraseña, DNI como usuario, o nombre de usuario.
 * - Acceso a todos los cursos autorizados en los que el estudiante se inscribió.
 */
function authenticateParticipant(usernameInput, passwordInput) {
  if (!usernameInput || !passwordInput) {
    return {
      success: false,
      message: 'Por favor ingresa tu usuario y contraseña.'
    };
  }

  const uClean = cleanStr(usernameInput);
  const pClean = cleanStr(passwordInput);

  if (uClean.length < 3) {
    return {
      success: false,
      message: 'El usuario debe tener al menos 3 caracteres.'
    };
  }

  // Buscar coincidencia en la base de datos oficial
  const match = STUDENTS_DATABASE.find(st => {
    const dniClean = st.dni ? cleanStr(st.dni) : '';
    const pRecord = st.p ? cleanStr(st.p) : '';
    const uRecord = cleanStr(st.u);
    const nRecord = cleanStr(st.n);
    const eRecord = cleanStr(st.e);

    // 1. Coincidencia de contraseña
    const matchesPassword = (pClean === pRecord) || 
                            (dniClean && pClean === dniClean) || 
                            (pClean === uRecord) || 
                            (pClean === nRecord);

    // 2. Coincidencia de usuario
    const matchesUser = (uClean === uRecord) || 
                        (uClean === nRecord) || 
                        (dniClean && uClean === dniClean) || 
                        (uClean === eRecord) || 
                        (st.k && st.k.some(kw => cleanStr(kw) === uClean));

    // Regla principal: Usuario coincide y Contraseña coincide
    if (matchesUser && matchesPassword) return true;

    // Si ingresó su DNI como usuario y su DNI como contraseña
    if (dniClean && uClean === dniClean && pClean === dniClean) return true;

    // Si ingresó su nombre como usuario y contraseña
    if ((uClean === uRecord || uClean === nRecord) && uClean === pClean) return true;

    // Si ingresó DNI como contraseña y el nombre coincide parcialmente
    if (dniClean && pClean === dniClean) {
      if (st.k && st.k.some(kw => cleanStr(kw).includes(uClean) || uClean.includes(cleanStr(kw)))) return true;
    }

    return false;
  });

  if (match) {
    const studentCourses = match.courses || ['bootcamp-portugues-cero'];
    const studentRole = match.role || 'Estudiante Inscrito';

    return {
      success: true,
      student: {
        name: match.n,
        shortName: match.u,
        email: match.e,
        dni: match.dni || null,
        role: studentRole,
        passportNo: 'PM-' + Math.abs(match.n.split('').reduce((a, b) => ((a << 5) - a) + b.charCodeAt(0), 0) % 9000 + 1000),
        allowedCourses: studentCourses
      }
    };
  }

  return {
    success: false,
    message: 'Usuario o contraseña no encontrados en la lista oficial. Si te inscribiste a partir del 11 de noviembre tu contraseña es tu DNI.'
  };
}

if (typeof window !== 'undefined') {
  window.STUDENTS_DATABASE = STUDENTS_DATABASE;
  window.authenticateParticipant = authenticateParticipant;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { STUDENTS_DATABASE, authenticateParticipant };
}
